function pdfWrapText(text,font,size,maxWidth){const paragraphs=String(text||'').replace(/\r/g,'').split('\n'),lines=[];paragraphs.forEach(paragraph=>{if(!paragraph.trim()){lines.push('');return}const words=paragraph.trim().split(/\s+/);let line='';words.forEach(word=>{const candidate=line?`${line} ${word}`:word;if(font.widthOfTextAtSize(candidate,size)<=maxWidth)line=candidate;else{if(line)lines.push(line);line=word}});if(line)lines.push(line)});return lines.length?lines:['']}
